mapper.update:
UPDATE tc_eqp_param
   SET param_value = #{e.paramValue},
       description = #{e.description},
       updated_at  = CURRENT_TIMESTAMP
 WHERE eqp_key = #{e.eqpKey}
   AND param_name = #{e.paramName}
   AND param_version = #{e.paramVersion}

mapper.select:
SELECT 
  FROM tc_eqp_param
 WHERE eqp_key = #{eqpKey}
   AND param_name = #{paramName}
   AND param_version = #{paramVersion}

SELECT 
  FROM tc_eqp_param
 WHERE eqp_key = #{eqpKey}
 ORDER BY eqp_param_key ASC

    LIMIT #{limit} OFFSET #{offset}
